const i={web3_267:{lianjieqianbao:"Подключить кошелек",wodeqianbaodizhi:"Адрес моего кошелька",licai:"Майнинг",jinrulicai:"Войти в майнинг",yishouyi:"Полученный доход",shouyilv:"Доходность",zhiyajine:"Сумма майнинга",canyu:"Участвовать",shouyishijian:"Время дохода {amount}/{time}",yifafangshouyi:"Выплаченный доход",licaishuju:"Данные майнинга",zongchanliang:"Общий объем",youxiaojiedian:"Действительные узлы",canyuzhe:"Участники",yonghushouru:"Доход пользователя",liudongxinglicaishouyi:"Доход от майнинга ликвидности",shouyi:"Доход",licaishuoming:"Описание майнинга",weishenmeyaolicai:"Зачем заниматься майнингом?",weishenmeyaolicai_desc:"Майнинг — это процесс увеличения активов за счет рационального распределения средств и использования различных финансовых инструментов. Эффективный майнинг помогает бороться с инфляцией, увеличивать пассивный доход, достигать финансовой свободы и цели досрочного выхода на пенсию.",licaifengxian:"Какие риски связаны с майнингом?",licaifengxian_desc:"Риски майнинга включают рыночный риск, инфляционный риск, риск ликвидности, кредитный риск и операционный риск. Инвесторы должны выбирать продукты в соответствии со своей способностью принимать риски и диверсифицировать активы для снижения рисков.",xinshoruhekaishilicai:"Как новичкам начать майнинг?",xinshoruhekaishilicai_desc:"Новичкам следует сначала создать резервный фонд, понять свое финансовое положение, поставить цели, изучить основы инвестирования, начинать с низкорисковых продуктов, постепенно расширять портфель и постоянно учиться и корректировать стратегии.",qukuailianlicai_youshi:"Какие преимущества у блокчейн-майнинга?",qukuailianlicai_youshi_desc:"Блокчейн-майнинг обладает такими преимуществами, как децентрализация, высокая прозрачность, низкие транзакционные издержки, глобальная доступность и автоматическое исполнение смарт-контрактов, что обеспечивает инновационные решения для традиционного майнинга.",liudongxingzhiyashishenme:"Что такое майнинг ликвидности?",liudongxingzhiyashishenme_desc:"Майнинг ликвидности — это процесс блокировки криптоактивов в протоколе DeFi для обеспечения ликвидности и получения вознаграждений. Майнеры обычно получают долю комиссий за транзакции и вознаграждения в виде токенов управления, что является популярным способом получения пассивного дохода.",ruhepinggulicaichanpindefengxian:"Как оценить риски майнинговых продуктов?",ruhepinggulicaichanpindefengxian_desc:"При оценке рисков майнинговых продуктов следует учитывать волатильность доходов, исторические результаты, ликвидность, репутацию эмитента, срок инвестиций и рыночную среду, а также соотносить их со своей способностью принимать риски.",shouyibiao:"Таблица доходов",meirishouyi:"Ежедневный доход"}};export{i as default};
